import spacy

def replace_mask_token(gujarati_text, mask_token):
    # Load Gujarati language model
    nlp = spacy.load('gu_dev')

    # Process text with Gujarati language model
    doc = nlp(gujarati_text)

    # Find the mask token in the document
    masked_tok = next((token for token in doc if token.text == mask_token), None)

    # Replace the mask token with a suitable word from the options
    if masked_tok:
        for option in ['ભારત', 'ગુજરાત', 'સૌરાષ્ટ્ર', 'અમેરિકા']:
            if option in nlp.vocab:
                masked_tok.replace_with(nlp.vocab[option].text)
                break

    # Convert processed document back to Gujarati text
    gujarati_text = ' '.join([token.text for token in doc])

    return gujarati_text

