import java.util.Map;
import java.util.HashMap;

public class HypernymFinder {

    public static String findHypernym(String word, Map<String, String[]> hypernymDict) {
        for (Map.Entry<String, String[]> entry : hypernymDict.entrySet()) {
            String[] synonyms = entry.getValue();
            if (Arrays.asList(synonyms).contains(word)) {
                return entry.getKey();
            }
        }
        return null;
    }

    public static void main(String[] args) {
        Map<String, String[]> hypernymDict = new HashMap<>();
        hypernymDict.put("boat", new String[]{"ship", "craft", "vessel"});
        hypernymDict.put("vehicle", new String[]{"transportation", "machine", "apparatus"});
        hypernymDict.put("weapon", new String[]{"armament", "military equipment", "instrument of war"});

        String hypernym = findHypernym("boat", hypernymDict);
        System.out.println(hypernym); // Output: ship

        hypernym = findHypernym("car", hypernymDict);
        System.out.println(hypernym); // Output: vehicle

        hypernym = findHypernym("knife", hypernymDict);
        System.out.println(hypernym); // Output: weapon

        hypernym = findHypernym("tree", hypernymDict);
        System.out.println(hypernym); // Output: null
    }

}﻿#C# code for finding hypernyms###

