            .zip(Array("Feature1", "Feature2", "Feature3", "Feature4", "Feature5")).toList.sortBy(-_._2): _*
        )
      }
      .collect
      .sortBy(_._1, ascending = false)
      .take(5) // Choose the top 5 most important features

    // Print the top 5 most important features
    println("Top 5 Most Important Features:")
    importantFeatures.foreach { case (feature, score) =>
      println(s"$feature: $score")
    }
  }
}
