import Foundation

struct NewsArticle {
    let title: String
    let description: String
    let url: URL
}

class NetworkManager {

    // Define a function to fetch news articles from API
    func fetchNewsArticles(completion: @escaping ([NewsArticle]?, Error?) -> Void) {

        // Define the API endpoint URL
        let url = "https://newsapi.org/v2/top-headlines?country=us&apiKey=YOUR_API_KEY"

        let task = URLSession.shared.dataTask(with: URL(string: url)!) { (data, response, error) in

            guard let data = data, let response = response as? HTTPURLResponse, response.statusCode == 200 else {
                completion(nil, error)
                return
            }

            do {
                let json = try JSONSerialization.jsonObject(with: data, options: []) as! [String: Any]
                let articles = json["articles"] as! [[String: Any]]

                var newsArticles: [NewsArticle] = []

                for article in articles {
                    guard let title = article["title"] as? String,
                        let description = article["description"] as? String,
                        let url = article["url"] as? String else {
                        completion(nil, nil)
                        return
                    }

                    let articleURL = URL(string: url)
                    newsArticles.append(NewsArticle(title: title, description: description, url: articleURL!))
                }

                completion(newsArticles, nil)

            } catch {
                completion(nil, error)
            }
        }

        task.resume()
    }
}

// Usage example:

let networkManager = NetworkManager()

networkManager.fetchNewsArticles { (articles, error) in
    if let articles = articles {
        for article in articles {
            print("Title: \(article.title)")
            print("Description: \(article.description)")
            print("URL: \(article.url)")
            print("\n")
        }
    } else if let error = error {
        print("Error fetching news articles: \(error)")
    }
}

