% Теоремы и определения
\begin{frame}{Определение и суть концепции}
  \begin{itemize}
    \item Линейный оператор $A$ называется сопряженным к линейному оператору $B$ (или $A \cong B$), если для любых векторов $x,y \in \mathbb{C}^n$ верно, что
      \begin{multline*}
        (Ax \mid y) = (x \mid B y) \\
        \text{или в виде матриц: } A^* = B
      \end{multline*}
      где $(\cdot \mid \cdot)$ обозначает скалярное произведение и $A^*$ - сопряженная матрица к $A$.
  \end{itemize}
\end{frame}

% Примеры применения и примеры задач
\begin{frame}{Приложения сопряженности}
  \begin{itemize}
    \item Методы итераций для решения систем линейных уравнений: если мы имеем две несколько близкие матрицы $A$ и $B$ в декартовой координатной базисе, и знаем, что $A^* = B$, то можно использовать итерационный метод, основанный на сопряжении для нахождения решения системы с матрицей $A$, при этом получая вектор, близкий к решению системы с матрицей $B$.
      \begin{align*}
        &x_0 \in \mathbb{C}^n \text{ произвольный начальный вектор} \\
        &\text{Для } j > 0: \\
        &\quad x_j = Ax_{j-1} + (B - A)x_{j-1}
      \end{align*}
    \item Граничные задачи для уравнений с частными производными: если уравнение с частными производными в двумерном случае может быть записано в виде системы из двух уравнений для двух неизвестных функций, и если мы знаем граничные условия для одной из этих функций, можно получить такое же условие для другой функции посредством применения сопряженности оператора определения этого уравнения.
      \begin{align*}
        &\frac{\partial u(x,t)}{\partial t} = k \frac{\partial^2 u(x,t)}{\partial x^2}, \quad 0 < x < L, \ t > 0 \\
        &u(0,t) = f(t), \quad u(L,t) = 0, \quad t > 0 \\
        &u(x,0) = g(x), \quad 0 \leq x \leq L
      \end{align*}
      \begin{align*}
        &\frac{\partial v(x,t)}{\partial t} = -k \frac{\partial^2 v(x,t)}{\partial x^2}, \quad 0 < x < L, \ t > 0 \\
        &v(0,t) = 0, \quad v(L,t) = f(t), \quad t > 0 \\
        &v(x,0) = g(x), \quad 0 \leq x \leq L
      \end{align*}
      где $v(x,t)$ является сопряженной функцией к $u(x,t)$, и $f(t)$ и $g(x)$ границы для функции $u(x,t)$.
  \end{itemize}
\end{frame}

