  mounted() {
    this.$emit('some-event');
    // @Suppress tslint:no-side-effects-in-mounted
  },
  // ...

  updated() {
    this.$dispatch('another-event');
    // @Suppress tslint:no-side-effects-in-updated
  },
};
```

Alternatively, you can add an `allowedSideEffects` array at the beginning of your `.eslintrc.js` file to whitelist specific methods that are allowed to have side effects:

```js
