  extends: ['plugin:vue/recommended'],

  rules: {
    // ...
    'vue/no-side-effects-in-lifecycle-hooks': {
      // ...
      defaultProps: {
        allowedSideEffects: ['push', '$emit'], // allowed methods to have side effects
      },
    },
    // ...
  },
};
