      create(context) {
        const { options, report } = context;
        const modifiedProps = new Set();

        function checkProp(path) {
          const propName = path.node.objectProperty.name.name;
          if (path.parentPath.isObjectProperty()) {
            const assignExpr = path.parentPath.parentPath.node;
            if (!assignExpr.isAssignmentExpression()) return;
            const leftSide = assignExpr.left;
            if (!leftSide.isMemberExpression()) return;

            const objectProp = leftSide.object;
            if (!objectProps.hasObjectProp(objectProp, propName)) {
              return;
            }
            const value = leftSide.property.name.name;

            if (value === 'this' && assignExpr.operator === '=') {
              const succeedingPath = path.parentPath.get('value');
              succeedingPath.forEach(path => {
