                    node: path.node,
                    message: `Avoid modifying "${propName}" property directly inside "${path.parentPath.parentPath.node.label}" lifecycle hook. Use a computed property or setter instead. `,
                    fix: fixer => {
                      const newValue = path.parentPath.parentPath.node;
                      const computedProperty = fixer.insertAfter(
                        path.parentPath.parentPath.node,
                        {
                          type: 'MemberExpression',
                          computed: true,
                          object: { type: 'ThisExpression' },
                          property: {
                            type: 'Identifier',
                            name: propName,
                          },
                        }
