                      return fixer.replaceText(newValue, `${computedProperty}`);
                    },
                  });
                }
              });
            }
          }
        }

        function addModifiedProps(path) {
          const { node } {
            if (node.type === 'ObjectExpression') {
              node.properties.forEach(property => {
