                    if (leftSide.type === 'MemberExpression') {
                      const objectProp = leftSide.object;
                      const propName = leftSide.property.name.name;
                      if (
                        objectProps.hasObjectProp(objectProp, propName) &&
                        !modifiedProps.has(propName)
                      ) {
