2. Далее возьмите следующий код и создайте файл в вашем проекте с именем `methods-invalid-internal-state.js`, расположенным в папке `rules`:

```js
module.exports = {
  meta: {
    type: "suggestion",
    fixable: "code",
    helps: {
      description: "Warn when lifecycle hooks have methods changing internal state.",
    },
  },

  create: function (context) {
    return {
      "MethodDefinition:method[*]": function (node) {
        const methodName = node.key.name;
        const methodBody = node.value.body;

        // Check if method modifies internal state
        const modifiedProps = methodBody
          .find((statementNode) => {
            return statementNode.type === "ExpressionStatement" && statementNode.expression.type === "MemberExpression";
          })
          .expression.object.name === "this" &&
          (statementNode.expression.property.name === "data" || statementNode.expression.property.name === "props");

        if (!methodName.startsWith("before") && !methodName.startsWith("updated") && modifiedProps) {
          context.report({
            node,
            message: `Method "${methodName}" should not modify internal state (e.g. This.data or this.props)`,
            fix: (fixer) => {
              // Check if method calls other internal state modifying methods
              const calledInternalStateMethods = methodBody
                .filter((statementNode) => statementNode.type === "CallExpression")
                .some((callNode) => {
                  return callNode.callee.property.name === "data" || callNode.callee.property.name === "props";
                });

              if (calledInternalStateMethods) {
                return [
                  fixer.insertTextBefore(node, "\n/* eslint-disable @vue/methods-invalid-internal-state */\n"),
                  fixer.insertTextAfter(node, "\n/* eslint-enable @vue/methods-invalid-internal-state */\n"),
                ].flat();
              }

              return [
                fixer.remove(node),
              ];
            },
          });
