Следующая конфигурация правил ESLint создает два новых правила для проверки Vue хуков жизненного цикла:

1. `vue-hooks-change-state`: Проверяет, содержит ли хук жизненного цикла только методы, которые не меняют внутреннее состояние компонента (например, `created` или `destroyed`).

Регулярный выражение проверяет, не содержит ли метод в хуке выражения `this.`, `vm.`, `this.$` или `vm.$`. Эти выражения могут изменять состояние компонента (например, `this.someData = "new value"`, `vm.$data.someProperty = ...`, и т. Д.).

```javascript
function isStateChangingExpression(expression) {
  return (
    expression.source.type === "MemberExpression" &&
    (expression.object.name === "this" || expression.object.name === "vm") &&
    (expression.property.name === "$" ||
      expression.property.object.name === "this" ||
      expression.property.object.name === "vm")
  );
}

function hasStateChangingExpressions(callExpressions) {
  return callExpressions.some((call) => {
    return (
      call.arguments.some((arg) =>
        isStateChangingExpression(arg.callee.expression)
      ) ||
      call.arguments.some((arg) =>
        hasStateChangingExpressions(arg.elements)
      )
    );
  });
}

module.exports = {
  meta: {
    docs: {
      description: "Prohibits hooks from changing component state.",
      category: "Vue",
    },
    schema: [],
  },
  create: function (context) {
    return {
      "VueHook": (node) => {
        const hookName = node.key.name;
        const body = node.body.body;

        if (
          ["beforeCreate", "created", "beforeMount", "mounted", "beforeUpdate", "updated", "beforeDestroy", "destroyed"].indexOf(
            hookName
          ) !== -1
        ) {
          body.forEach((statement) => {
            if (
              statement.type === "ExpressionStatement" &&
              statement.expression.type === "CallExpression" &&
              hasStateChangingExpressions(statement.expression.arguments)
            ) {
              context.report({
                node,
                message: `Prohibiting hook "${hookName}" from changing component state. Call to state changing method found.`,
              });
            }
          });
        }
      },
    };
  },
};
```

2. `vue-hooks-change-state-call`: Проверяет, не вызываются ли внутри методов хука жизненного цикла другие методы, которые изменяют внутреннее состояние компонента.

Регулярный выражение проверяет, не содержит ли метод вызовы других методов, которые могут изменять состояние компонента (например, `this.someMethod()` или `vm.$someMethod()`).

