  return (
    expression.arguments && expression.arguments.length > 0 &&
    (expression.arguments[0].type === "Identifier" &&
      (expression.arguments[0].name === "$" &&
        expression.callee.object.name === "vm" &&
        expression.callee.property.name === "data") ||
      expression.arguments[0].type === "MemberExpression" &&
      expression.arguments[0].object.name === "this" &&
      (expression.arguments[0].property.name === "$" &&
        expression.callee.object.name === "vm" &&
        expression.callee.property.name === "data") ||
      (expression.arguments[0].type === "MemberExpression" &&
        expression.arguments[0].object.name === "vm" &&
        (expression.arguments[0].property.name === "$data" ||
          expression.arguments[0].property.object.name === "this" &&
          expression.arguments[0].property.property.name === "$data")) ||
      (expression.arguments[0].type === "Identifier" &&
        (expression.arguments[0].name === "$data" ||
          expression.arguments[0].name === "this.$data")))
  );
}

