require 'open-uri/httpclient'
require 'open-uri/httpcookiejar'
require 'nokogiri'

class Scraper
  attr_reader :url

  def initialize(url)
    @url = url
    @client = HTTPClient.new(cookiejar: HTTPCookieJar.new)
  end

  def scrape
    page = Nokogiri::HTML(@client.get_content(@url))
    content = page.css('.article-content')

    title = content.css('h1').text.strip
    date = content.css('.article-date').text.strip
    author = content.css('.article-author').text.strip

    { title: title, date: date, author: author, content: content.to_html }
  end
end

