const fs = require('fs');
const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

function processLine(line) {
  // Process each line here
  console.log(line.trim()); // Example: just print the line
}

function processFile(filename) {
  return new Promise((resolve, reject) => {
    fs.createReadStream(filename)
      .pipe(process.stdin)
      .on('pipe', () => {
        rl.on('line', line => processLine(line));
        rl.on('close', () => {
          rl.close();
          resolve();
        });
      })
      .on('error', err => reject(err));
  });
}

async function main() {
  const filename = 'example.txt';

  try {
    await processFile(filename);
    console.log('Done!');
  } catch (err) {
    console.error(err);
    process.exit(1);
  }
}

main();
```

This JavaScript program reads the contents of a text file, specified by `filename`, and processes each line (in the `processLine` function, we only print the line to the console in this example).

To run this program, save it as a JavaScript file (e.g. `process_file.js`) and execute it with the following command:

```
